#!/usr/bin/env python3
"""An independent HTML-to-Markdown command line converter.

The parser, selectors, Markdown layout and command-line interface use only the
Python standard library.  No other converter is invoked by this program.
"""
import fnmatch
import glob
import html
from html.parser import HTMLParser
import os
import re
import sys
from urllib.parse import urlsplit, urlunsplit, urljoin, quote


class Node:
    def __init__(self, tag='', attrs=None, text=''):
        self.tag = tag
        self.attrs = dict(attrs or [])
        self.text = text
        self.children = []
        self.parent = None

    def append(self, n):
        if n.parent is not None:
            n.parent.children.remove(n)
        n.parent = self
        self.children.append(n)
        return n

    def detach(self):
        if self.parent is not None:
            self.parent.children.remove(self)
            self.parent = None

    def descendants(self):
        for n in self.children:
            yield n
            yield from n.descendants()

    def text_content(self):
        if not self.tag:
            return self.text
        return ''.join(n.text_content() for n in self.children)


VOID = set('area base br col embed hr img input keygen link meta param source track wbr'.split())
BLOCK = set('address article aside dd details dialog div dl dt fieldset figcaption figure footer form hgroup li main nav p section'.split())
PARABREAK = BLOCK | set('blockquote center dir h1 h2 h3 h4 h5 h6 hr listing menu ol pre table ul'.split())
HEAD = set('base basefont bgsound link meta title noframes noscript script style template'.split())
RAW = set('script style xmp iframe noembed noframes noscript plaintext'.split())
DROP = set('script style noscript iframe textarea'.split())
EMPH = {'b': 'strong', 'strong': 'strong', 'em': 'em', 'i': 'em'}
STRIKE = set('s strike del'.split())
CODE = set('code kbd samp tt var'.split())


class TreeParser(HTMLParser):
    """Small, forgiving HTML tree builder with the implied HTML containers."""
    CDATA_CONTENT_ELEMENTS = tuple(RAW | {'textarea', 'title'})

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node('#document')
        self.html = self.root.append(Node('html'))
        self.head = self.html.append(Node('head'))
        self.body = self.html.append(Node('body'))
        self.stack = [self.html]
        self.inbody = False
        self.pre_newline = None
        self.active = []

    def current(self):
        return self.stack[-1]

    def index_open(self, tag, barriers=()):
        for i in range(len(self.stack) - 1, 0, -1):
            t = self.stack[i].tag
            if t == tag:
                return i
            if t in barriers:
                break
        return None

    def close(self, tag, barriers=()):
        i = self.index_open(tag, barriers)
        if i is not None:
            del self.stack[i:]
            return True
        return False

    def ensure_body(self):
        if not self.inbody:
            self.inbody = True
            self.stack = [self.html, self.body]

    def add(self, n, foster=False):
        if foster:
            ti = self.index_open('table')
            if ti is not None:
                table = self.stack[ti]
                parent = table.parent
                if parent:
                    n.parent = parent
                    idx = parent.children.index(table)
                    if not n.tag and idx and not parent.children[idx-1].tag:
                        parent.children[idx-1].text += n.text
                        return parent.children[idx-1]
                    parent.children.insert(idx, n)
                    return n
        p = self.current()
        if not n.tag and p.children and not p.children[-1].tag:
            p.children[-1].text += n.text
            return p.children[-1]
        return p.append(n)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag in ('svg', 'math'):
            self.handle_endtag(tag)

    def handle_starttag(self, tag, attrs):
        # HTML attributes use the first occurrence, not the last.
        att = {}
        for k,v in attrs:
            if k not in att:
                att[k] = v if v is not None else ''
        if tag == 'html':
            for k,v in att.items():
                self.html.attrs.setdefault(k,v)
            return
        if tag == 'head':
            if not self.inbody:
                self.stack = [self.html, self.head]
                self.head.attrs.update(att)
            return
        if tag == 'body':
            self.ensure_body()
            self.body.attrs.update(att)
            return
        if not self.inbody:
            if tag in HEAD or self.current().tag not in ('html', 'head'):
                if self.current() is self.html:
                    self.stack.append(self.head)
            else:
                self.ensure_body()
        if self.current().tag == 'select' and tag not in ('option', 'optgroup', 'script', 'template', 'hr'):
            if tag in ('input','textarea','select'):
                self.close('select')
                if tag == 'select':
                    return
            else:
                return
        if tag in PARABREAK:
            self.close('p', ('table','td','th','button'))
        if tag == 'li':
            self.close('li', ('ul','ol'))
        if tag in ('dt', 'dd'):
            for t in ('dt', 'dd'):
                if self.close(t, ('dl',)):
                    break
        if re.fullmatch('h[1-6]',tag):
            if re.fullmatch('h[1-6]',self.current().tag):
                self.stack.pop()
        if tag == 'option':
            self.close('option', ('select','datalist'))
        if tag == 'optgroup':
            self.close('option', ('select',))
            self.close('optgroup', ('select',))
        if tag == 'a':
            self.close('a')
        # Tables require rows/cells to be in table scope. Text is fostered out.
        if tag in ('tbody','thead','tfoot','tr','td','th','caption','colgroup','col'):
            if self.index_open('table') is None:
                return
            if tag in ('tbody','thead','tfoot'):
                for t in ('td','th','tr','tbody','thead','tfoot'):
                    self.close(t, ('table',))
            if tag == 'tr':
                for t in ('td','th','tr'):
                    self.close(t, ('table',))
                if self.current().tag == 'table':
                    self.stack.append(self.add(Node('tbody')))
            if tag in ('td','th'):
                for t in ('td','th'):
                    self.close(t, ('table',))
                if self.current().tag == 'table':
                    self.stack.append(self.add(Node('tbody')))
                if self.current().tag in ('tbody','thead','tfoot'):
                    self.stack.append(self.add(Node('tr')))
            if tag == 'col' and self.current().tag == 'table':
                self.stack.append(self.add(Node('colgroup')))
        foster = self.current().tag in ('table','tbody','thead','tfoot','tr') and tag not in ('tbody','thead','tfoot','tr','td','th','caption','colgroup','col','style','script','template')
        n = self.add(Node(tag,att), foster)
        if tag not in VOID:
            self.stack.append(n)
        if tag in ('pre','listing','textarea'):
            self.pre_newline = n

    def handle_endtag(self, tag):
        self.pre_newline = None
        if tag in ('html','body'):
            return
        if tag == 'head':
            if not self.inbody:
                self.stack = [self.html]
            return
        if tag == 'br':
            self.handle_starttag('br', [])
            return
        if tag == 'p' and self.index_open('p') is None:
            self.handle_starttag('p', [])
        self.close(tag)

    def handle_data(self, data):
        if not data:
            return
        if self.current().tag in ('textarea','title'):
            data = html.unescape(data)
        if self.pre_newline is self.current():
            if data.startswith('\n'):
                data = data[1:]
            self.pre_newline = None
        data = data.replace('\0', '')
        if not self.inbody and self.current().tag in ('html','head'):
            if data.strip(' \t\r\n\f'):
                self.ensure_body()
            else:
                if self.current() is self.html:
                    return
        if data:
            foster = self.current().tag in ('table','tbody','thead','tfoot','tr') and bool(data.strip())
            self.add(Node(text=data), foster)

    def handle_comment(self, data):
        pass

    def unknown_decl(self, data):
        pass


def parse_html(source):
    p = TreeParser()
    source = source.replace('\r\n','\n').replace('\r','\n')
    try:
        p.feed(source)
        p.close()
    except (ValueError, AssertionError):
        pass
    # HTMLParser leaves an unfinished raw-text element in its input buffer.
    if p.rawdata and p.cdata_elem:
        p.handle_data(p.rawdata)
    return p.root


class SelectorError(Exception):
    pass


def split_top(s, delim=','):
    parts=[]
    start=0
    depth=0
    quoted=''
    escaped=False
    for i,c in enumerate(s):
        if escaped:
            escaped=False
            continue
        if c=='\\':
            escaped=True
            continue
        if quoted:
            if c==quoted:
                quoted=''
            continue
        if c in '\"\'':
            quoted=c
        elif c in '([':
            depth+=1
        elif c in ')]':
            depth-=1
        elif c==delim and depth==0:
            parts.append(s[start:i])
            start=i+1
    parts.append(s[start:])
    return parts


class Selector:
    def __init__(self, expression):
        self.expression=expression
        if not expression.strip():
            raise SelectorError('empty string')
        self.groups=[self.parse_group(x.strip()) for x in split_top(expression)]

    @staticmethod
    def ident(s, i):
        m=re.match(r'(?:[\w\-\u0080-\uffff]|\\.)+',s[i:])
        if not m:
            if i>=len(s):
                raise SelectorError('expected identifier, found EOF instead')
            raise SelectorError('expected identifier, found '+s[i:]+' instead')
        return re.sub(r'\\(.)',r'\1',m.group()), i+len(m.group())

    def parse_group(self,s):
        parts=[]
        i=0
        combinator=' '
        while i<len(s):
            tests=[]
            if s[i]=='*':
                i+=1
            elif s[i] not in '#.[:':
                name,i=self.ident(s,i)
                tests.append(('tag',name.lower()))
            while i<len(s) and s[i] in '#.[:':
                c=s[i]; i+=1
                if c in '#.':
                    name,i=self.ident(s,i)
                    tests.append(('id' if c=='#' else 'class',name))
                elif c=='[':
                    name,i=self.ident(s,i)
                    while i<len(s) and s[i].isspace(): i+=1
                    if i>=len(s): raise SelectorError('unexpected EOF in attribute selector')
                    if s[i]==']':
                        tests.append(('attr',name.lower(),None,None));i+=1
                        continue
                    m=re.match(r'([~|^$*!]?=)\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s\]]+))\s*([iIsS]?)\s*\]',s[i:])
                    if not m: raise SelectorError('unexpected EOF in attribute selector' if ']' not in s[i:] else 'expected attribute selector operator')
                    op=m.group(1); value=next((v for v in m.group(2,3,4) if v is not None),'')
                    tests.append(('attr',name.lower(),op,value,m.group(5).lower()))
                    i+=len(m.group())
                else:
                    pseudo_element=i<len(s) and s[i]==':'
                    if pseudo_element: i+=1
                    name,i=self.ident(s,i)
                    if pseudo_element or name in ('before','after','first-line','first-letter'):
                        raise SelectorError('pseudo-element '+name+' found, but pseudo-elements support is disabled')
                    arg=None
                    if i<len(s) and s[i]=='(':
                        beg=i+1; level=1; q=''; i+=1
                        while i<len(s):
                            c2=s[i]
                            if q:
                                if c2==q and s[i-1]!='\\':q=''
                            elif c2 in '\"\'':q=c2
                            elif c2=='(':level+=1
                            elif c2==')':
                                level-=1
                                if level==0:break
                            i+=1
                        if level: raise SelectorError('unexpected EOF in pseudo-class argument')
                        arg=s[beg:i].strip();i+=1
                    known={'not','is','where','matches','has','haschild','contains','containsown','matchesown','empty','root','first-child','last-child','only-child','first-of-type','last-of-type','only-of-type','nth-child','nth-last-child','nth-of-type','nth-last-of-type','enabled','disabled','checked','link','any-link','visited','lang','input','header','button','text'}
                    if name not in known:
                        raise SelectorError('unknown pseudoclass or pseudoelement :'+name)
                    if name in ('not','is','where','has','haschild'):
                        arg=Selector(arg or '')
                    tests.append(('pseudo',name,arg))
            parts.append((combinator,tests))
            space=False
            while i<len(s) and s[i].isspace():i+=1;space=True
            if i>=len(s): break
            if s[i] in '>+~':
                combinator=s[i];i+=1
                while i<len(s) and s[i].isspace():i+=1
                if i>=len(s): raise SelectorError('expected selector, found EOF instead')
            elif space:
                combinator=' '
            else:
