        return parts

    def matches(self,n):
        if not n.tag or n.tag.startswith('#'):
            return False
        return any(self.match_part(n,g,len(g)-1) for g in self.groups)

    def match_part(self,n,parts,i):
        if n is None or not n.tag or not self.simple(n,parts[i][1]):return False
        if i==0:return True
        c=parts[i][0]
        if c=='>': return self.match_part(n.parent,parts,i-1)
        if c in ('+','~'):
            if n.parent is None:return False
            sib=[x for x in n.parent.children if x.tag]
            pos=sib.index(n)
            if c=='+':return pos>0 and self.match_part(sib[pos-1],parts,i-1)
            return any(self.match_part(x,parts,i-1) for x in sib[:pos])
        a=n.parent
        while a is not None:
            if self.match_part(a,parts,i-1):return True
            a=a.parent
        return False

    def simple(self,n,tests):
        for t in tests:
            if t[0]=='tag' and n.tag!=t[1]:return False
            if t[0]=='id' and n.attrs.get('id')!=t[1]:return False
            if t[0]=='class' and t[1] not in n.attrs.get('class','').split():return False
            if t[0]=='attr':
                name,op,v=t[1:4]
                if name not in n.attrs:
                    if op=='!=':continue
                    return False
                if op:
                    val=n.attrs[name]
                    if len(t)>4 and t[4]=='i':val=val.lower();v=v.lower()
                    yes={'=':lambda:val==v,'!=':lambda:val!=v,'~=':lambda:v in val.split(),'|=':lambda:val==v or val.startswith(v+'-'),'^=':lambda:bool(v) and val.startswith(v),'$=':lambda:bool(v) and val.endswith(v),'*=':lambda:bool(v) and v in val}.get(op,lambda:False)()
                    if not yes:return False
            if t[0]=='pseudo' and not self.pseudo(n,t[1],t[2]):return False
        return True

    def pseudo(self,n,name,arg):
        if name in ('not','is','where'):
            ok=arg.matches(n)
            return not ok if name=='not' else ok
        if name in ('has','haschild'):
            return any(arg.matches(x) for x in (n.children if name=='haschild' else n.descendants()))
        if name in ('contains','containsown'):
            text=n.text_content() if name=='contains' else ''.join(x.text for x in n.children if not x.tag)
            return (arg or '').strip('\"\'').lower() in text.lower()
        if name in ('matches','matchesown'):
            try:return bool(re.search(arg or '',n.text_content()))
            except re.error:return False
        if name=='empty':return not any(x.tag or x.text for x in n.children)
        if name=='root':return n.tag=='html'
        if name=='checked':return 'checked' in n.attrs or ('selected' in n.attrs and n.tag=='option')
        if name in ('enabled','disabled'):
            return n.tag in ('input','button','select','option','optgroup','textarea','fieldset') and (('disabled' in n.attrs)==(name=='disabled'))
        if name in ('link','any-link'):return n.tag in ('a','area','link') and 'href' in n.attrs
        if name=='visited':return False
        if name=='lang':
            a=n
            while a:
                lang=a.attrs.get('lang','').lower()
                if lang:return lang==(arg or '').lower() or lang.startswith((arg or '').lower()+'-')
                a=a.parent
            return False
        if name=='input':return n.tag in ('input','select','textarea','button')
        if name=='header':return bool(re.fullmatch('h[1-6]',n.tag))
        if name=='button':return n.tag=='button' or (n.tag=='input' and n.attrs.get('type')=='button')
        if name=='text':return n.tag=='input' and n.attrs.get('type','text')=='text'
        sib=[x for x in (n.parent.children if n.parent else [n]) if x.tag]
        if 'of-type' in name:sib=[x for x in sib if x.tag==n.tag]
        if n not in sib:return False
        idx=sib.index(n)+1
        if name.startswith('first-'):return idx==1
        if name.startswith('last-'):return idx==len(sib)
        if name.startswith('only-'):return len(sib)==1
        if name.startswith('nth-'):
            if name.startswith('nth-last'):idx=len(sib)+1-idx
            a=(arg or '').replace(' ','').lower()
            if a=='odd':a='2n+1'
            if a=='even':a='2n'
            if re.fullmatch(r'[+-]?\d+',a):return idx==int(a)
            m=re.fullmatch(r'([+-]?\d*)n([+-]\d+)?',a)
            if not m:return False
            factor={'':1,'+':1,'-':-1}.get(m[1],int(m[1]) if m[1] not in ('','+','-') else 1)
            off=int(m[2] or 0)
            return idx==off if factor==0 else (idx-off)%factor==0 and (idx-off)//factor>=0
        return False


# Raw punctuation is distinguished from Markdown syntax until layout is complete.
RAW_CHARS = '\\`*_~[]<>#+-=.)|'
ENC = {c:chr(0xe100+i) for i,c in enumerate(RAW_CHARS)}
DEC = {v:k for k,v in ENC.items()}
ENC_TRANS = str.maketrans(ENC)
DEC_TRANS = str.maketrans(DEC)
INDENT='\ue180'
LIST_BEGIN='\ue181'
LIST_END='\ue182'


def raw_text(s):
    return s.translate(ENC_TRANS)


def plain(s):
    return s.translate(DEC_TRANS)


def trim(s):
    return s.strip()


def clean(s):
    # Blocks may independently request their surrounding empty lines.
    s=re.sub(r'[ \t]*\n(?:[ \t]*\n)+[ \t]*','\n\n',s)
    return s.strip()


class Converter:
    def __init__(self,options):
        self.options=options
        self.strong=options.get('opt-strong-delimiter') or '**'
        self.strike=options.get('plugin-strikethrough',False)
        self.table_enabled=options.get('plugin-table',False)
        self.protected={}
        self.serial=0
        self.base=self.domain_url(options.get('domain',''))

    def hold(self,s):
        # One non-whitespace character is a token for an opaque piece of output.
        char=chr(0xf0000+self.serial)
        self.serial+=1
        self.protected[char]=s
        return char

    def restore(self,s):
        for k,v in self.protected.items():
            if k in s:s=s.replace(k,v)
        return s.replace(INDENT,' ').replace(LIST_BEGIN,'').replace(LIST_END,'')

    @staticmethod
    def domain_url(s):
        s=s.strip()
        if not s:return ''
        for value in (s,'http://'+s):
            try:
                p=urlsplit(value)
                if not p.netloc or re.search(r'[\s<>]',p.netloc):continue
                # Accessing .port verifies port syntax as in a URL parser.
                p.port
                return value
            except ValueError:pass
        return ''

    def url(self,s):
        s=s.strip()
        if self.base:
            try:
                if not re.search(r'%(?![0-9a-fA-F]{2})',s):
                    s=urljoin(self.base,s)
            except ValueError:pass
        return quote(s,safe=':/?#@!$&\'*,;=+[]%~-._').replace('[','%5B').replace(']','%5D')

    def title(self,s):
        if not s:return ''
        s=s.replace('\n',' ')
        if '"' in s and "'" not in s:
            return " '"+s+"'"
        return ' "'+s.replace('"','\\"')+'"'

    def normalize(self,root):
        def prune(n,pre=False):
            new=[]
            for c in list(n.children):
                if c.tag in DROP or c.tag=='head':
                    c.parent=None
                    continue
                prune(c,pre or n.tag=='pre')
                if c.tag and not c.children and c.tag not in VOID and c.tag not in BLOCK and c.tag not in ('pre','table','ul','ol','blockquote'):
                    continue
                # Formatting-free inline containers do not affect conversion.
                if c.tag in ('span','font','small','big','u','mark','q','abbr','acronym','cite','dfn','time','data','ins','sub','sup','nobr') or (c.tag in STRIKE and not self.strike):
                    for x in c.children:x.parent=n;new.append(x)
                else:
                    c.parent=n;new.append(c)
            n.children=new
            # Adjacent inline wrappers form a single formatting run.
            out=[]
            def group(x):
                if x.tag in EMPH:return 'emphasis'
                if x.tag in CODE:return 'code'
                if x.tag in STRIKE and self.strike:return 'strike'
                return None
            for c in n.children:
                if out and group(c) and group(c)==group(out[-1]):
                    old=out[-1]
                    for x in c.children:x.parent=old
                    old.children.extend(c.children)
                elif out and not c.tag and not out[-1].tag:
                    out[-1].text+=c.text
                else:out.append(c)
            n.children=out
        prune(root)
        state={'space':True,'last':None}
        def whitespace(n,pre=False):
            if not n.tag:
                if pre:return
                s=re.sub(r'[ \t\n\r]+',' ',n.text)
                if state['space'] and s.startswith(' '):s=s[1:]
                n.text=s
                if s:state['space']=s.endswith(' ');state['last']=n
                return
            if n.tag=='pre':
                state['space']=False;state['last']=None
                return
            block=n.tag in BLOCK or n.tag in ('blockquote','ul','ol','table','hr') or bool(re.fullmatch('h[1-6]',n.tag))
            if block:
                last=state['last']
                if last:last.text=last.text.rstrip(' ')
                state['space']=True;state['last']=None
            if n.tag in ('img','input','br','hr','source','wbr'):
                if n.tag=='br':
                    last=state['last']
                    if last:last.text=last.text.rstrip(' ')
                    state['space']=True
                else:state['space']=False
                state['last']=None
            for c in n.children:whitespace(c,pre)
            if block:
                last=state['last']
                if last:last.text=last.text.rstrip(' ')
                state['space']=True;state['last']=None
        whitespace(root)

    def convert(self,source):
        root=parse_html(source)
        excludes=self.options.get('exclude-selector',[])
        for n in list(root.descendants()):
            if n.parent and any(s.matches(n) for s in excludes):n.detach()
        includes=self.options.get('include-selector',[])
        if includes:
            nodes=[n for n in root.descendants() if any(s.matches(n) for s in includes)]
            new=Node('#document')
            for n in nodes:
                n.detach()
                container=new.append(Node('div'))
                container.append(n)
            root=new
        self.normalize(root)
        result=self.render(root)
        result=self.list_boundaries(result)
        result=clean(result)
        result=self.escape(result)
        result=self.restore(result)
        return result.strip()

    @staticmethod
    def list_boundaries(s):
        s=re.sub(LIST_END+r'\s*'+LIST_BEGIN,'\n\n<!--THE END-->\n\n',s)
        return s.replace(LIST_BEGIN,'').replace(LIST_END,'')

    def escape(self,s,lines=True):
        # Inline syntax needs escaping only if it could start a construct.
        out=[]
        for i,c in enumerate(s):
            raw=DEC.get(c)
            if raw is None:
                out.append(c);continue
            if raw=='\\':out.append('\\\\')
            elif raw=='`':out.append('\\`')
            elif raw=='<':out.append('&lt;')
            elif raw=='>':out.append('&gt;')
            elif raw in ('*','_') or (raw=='~' and self.strike):
                out.append(('\\' if i+1<len(s) and not s[i+1].isspace() else '')+raw)
            elif raw=='[':
                nxt=s.find('\n',i)
                stop=nxt if nxt!=-1 else len(s)
                out.append(('\\' if ENC[']'] in s[i+1:stop] or ']' in s[i+1:stop] else '')+'[')
            else:out.append(c)
        s=''.join(out)
        if lines:
            parts=s.split('\n')
            for i,line in enumerate(parts):
                dec=plain(line)
                # Only raw punctuation at the beginning of a line is changed.
                if line.startswith(ENC['#']) and re.match(r'^#{1,6}(?:\s|$)',dec):
                    line='\\'+line
                elif line[:1] in (ENC['-'],ENC['+']) and re.match(r'^[-+](?:\s|$)',dec):
                    line='\\'+line
                elif line.startswith('*') and re.match(r'^\*(?:\s|$)',dec):
                    line='\\'+line
                elif line.startswith(ENC['-']) and re.fullmatch(r'(?:-\s*){3,}',dec):
                    line='\\'+line
                elif line.startswith('_') and re.fullmatch(r'(?:_\s*){3,}',dec):
                    line='\\'+line
                elif re.match(r'^\d+['+ENC['.']+ENC[')']+r'](?:\s|$)',line):
                    m=re.match(r'^\d+',line)
                    line=line[:m.end()]+'\\'+line[m.end():]
                elif i>0 and parts[i-1].strip() and line[:1] in (ENC['='],ENC['-']) and re.fullmatch(r'=+|-+',dec):
                    line='\\'+line
                parts[i]=line
            s='\n'.join(parts)
        return plain(s)

    def children(self,n,inline=False,active=()):
        return ''.join(self.render(c,inline,active) for c in n.children)

    def code_text(self,n):
        if not n.tag:return n.text
        if n.tag=='br':return '\n'
        if n.tag in DROP:return ''
        return ''.join(self.code_text(c) for c in n.children)

    def inline_code(self,n):
        s=re.sub(r'[ \t\r\n]+',' ',self.code_text(n)).strip()
        if not s:return ''
        longest=max([len(m.group()) for m in re.finditer(r'`+',s)]+[0])
        fence='`'*(longest+1)
        if s.startswith('`') or s.endswith('`'):s=' '+s+' '
        return self.hold(fence+s+fence)

    def style(self,n,delimiter,active,kind):
        if kind in active:return self.children(n,True,active)
        substantive=[c for c in n.children if c.tag or c.text.strip()]
        if len(substantive)==1 and substantive[0].tag=='a':
            link=substantive[0]
            content=self.children(link,True,active+(kind,))
            return self.link(link,self.wrap_style(content,delimiter))
        s=self.children(n,True,active+(kind,))
        return self.wrap_style(s,delimiter)

    @staticmethod
    def wrap_style(s,delimiter):
        parts=re.split('(\n)',s)
        for i,p in enumerate(parts):
            if p and p!='\n' and p.strip():
                first=len(p)-len(p.lstrip())
                last=len(p.rstrip())
                parts[i]=p[:first]+delimiter+p[first:last]+delimiter+p[last:]
        return ''.join(parts)

    def link(self,n,s):
        s=clean(s)
        s=s.replace(ENC['['],'\\[').replace(ENC[']'],'\\]')
        # Inline links cannot contain a blank Markdown line.
        s=s.replace('\n\n','  \n\\\n')
        suffix=']('+self.url(n.attrs.get('href',''))+self.title(n.attrs.get('title',''))+')'
        return '['+s+self.hold(suffix)

    def render(self,n,inline=False,active=()):
        t=n.tag
        if not t:return raw_text(n.text)
        if t=='head' or t in DROP:return ''
        if t in ('#document','html','body'):return self.children(n,inline,active)
        if t in EMPH:
            k=EMPH[t]
            return self.style(n,self.strong if k=='strong' else '*',active,k)
        if t in STRIKE and self.strike:return self.style(n,'~~',active,'strike')
        if t in CODE:return self.inline_code(n)
        if t=='pre':
            if inline:return self.inline_code(n)
            s=self.code_text(n)
            lang=''
            for c in [n]+list(n.descendants()):
                for cl in c.attrs.get('class','').split():
                    if cl.startswith('language-'):lang=cl[9:];break
                    if cl.startswith('lang-'):lang=cl[5:];break
                if lang:break
            fence='`'*max([len(m.group())+1 for m in re.finditer('`+',s)]+[3])
            # Keep code whitespace out of block whitespace normalization.
            body=self.hold(s.rstrip('\n') if s.endswith('\n') else s)
            # Only one terminal newline belongs to the closing fence.
            if s.endswith('\n'):self.protected[body]=s[:-1]
            return '\n\n'+fence+lang+'\n'+body+'\n'+fence+'\n\n'
        if t=='br':return '  \n'
        if t=='hr':return '' if inline else '\n\n* * *\n\n'
        if re.fullmatch('h[1-6]',t):
            s=clean(self.children(n,True,active))
            s=re.sub(r'\s*\n\s*',' ',s)
            if not s:return ''
            if inline:return '\n\n'+self.strong+s+self.strong+'\n\n'
            if s.endswith(ENC['#']):s=s[:-1]+'\\#'
            return '\n\n'+'#'*int(t[1])+' '+s+'\n\n'
        if t=='a':return self.link(n,self.children(n,True,active))
        if t=='img':
            src=n.attrs.get('src','')
            if not src.strip():return ''
            alt=n.attrs.get('alt','').replace('\n',' ').replace('[','\\[').replace(']','\\]')
            return self.hold('!['+alt+']('+self.url(src)+self.title(n.attrs.get('title',''))+')')
        if t=='blockquote':
            s=clean(self.children(n,inline,active))
            if not s:return ''
            if inline:return ' "'+s+'" '
            return '\n\n'+'> '+s.replace('\n','\n> ')+'\n\n'
        if t in ('ul','ol'):
            if inline:return self.children(n,True,active)
            return self.list(n,active)
        if t=='li' and inline:return self.children(n,True,active)
        if t=='table':
            if self.table_enabled and not inline:
                s=self.table(n,active)
                if s is not None:return '\n\n'+s+'\n\n'
            return '\n\n'+self.children(n,inline,active)+'\n\n'
        if t in BLOCK:
            return '\n\n'+self.children(n,inline,active)+'\n\n'
        return self.children(n,inline,active)

    def list(self,n,active):
        items=[]
        pending=[]
        for c in n.children:
            if c.tag=='li':
                if pending:
                    text=clean(''.join(pending))
                    if text:items.append(text)
                    pending=[]
                items.append(clean(self.children(c,False,active)))
            else:
                s=self.render(c,False,active)
                if items:items[-1]+=s
                else:pending.append(s)
        if pending:items.append(clean(''.join(pending)))
        items=[clean(self.list_boundaries(x)) for x in items if clean(x)]
        if not items:return ''
        start=n.attrs.get('start','1') if n.tag=='ol' else '1'
        if not re.fullmatch(r'[+-]?\d+',start):start='1'
        try:ival=int(start)
        except ValueError:ival=1;start='1'
        nums=[str(ival+i) if i else start for i in range(len(items))]
        width=max(len(x) for x in nums)
        out=[]
        for i,s in enumerate(items):
            # Lists explicitly indent each code line as well as normal text.
            for k,v in list(self.protected.items()):
                if k in s and '\n' in v:
                    s=s.replace(k, self.hold(v.replace('\n','\n'+INDENT*(width+2 if n.tag=='ol' else 2))))
            s=self.escape(s)
            bullet=nums[i].zfill(width)+'. ' if n.tag=='ol' else '- '
            indent=INDENT*len(bullet)
            s=s.replace('\n','\n'+indent)
            out.append(bullet+s)
        return '\n\n'+LIST_BEGIN+'\n'.join(out)+LIST_END+'\n\n'

    def table(self,n,active):
        if n.attrs.get('role')=='presentation' and not self.options.get('opt-table-presentation-tables'):return None
        rownodes=[]
        def findrows(x):
            for c in x.children:
                if c.tag=='tr':rownodes.append(c)
                elif c.tag!='table':findrows(c)
        findrows(n)
        cells={}
        headers=[]
        rowcount=len(rownodes)
        maxcol=0
        align={}
        skip=self.options.get('opt-table-skip-empty-rows',False)
        mirror=self.options.get('opt-table-span-cell-behavior')=='mirror'
        preserve=self.options.get('opt-table-newline-behavior')=='preserve'
        for ri,row in enumerate(rownodes):
            col=0
            ishead=(row.parent is not None and row.parent.tag=='thead') or any(c.tag=='th' for c in row.children)
            if ishead:headers.append(ri)
            for c in row.children:
                if c.tag not in ('td','th'):continue
                while (ri,col) in cells:col+=1
                text=self.children(c,False,active).strip()
                if '\n' in text and not preserve:return None
                if preserve:text=text.replace('\n',self.hold('<br />'))
                text=text.replace(ENC['|'],'\\|')
                text=self.escape(text,lines=False)
                text=self.restore(text)
                def span(name):
                    try:return max(1,min(int(c.attrs.get(name,'1')),1000))
                    except ValueError:return 1
                cs=span('colspan');rs=span('rowspan')
                for rr in range(ri,min(ri+rs,rowcount)):
                    for cc in range(col,col+cs):
                        cells[(rr,cc)]=text if (mirror or (rr==ri and cc==col)) else ''
                if ishead and c.attrs.get('align') in ('left','center','right'):
                    for cc in range(col,col+cs):align.setdefault(cc,c.attrs['align'])
                col+=cs
                maxcol=max(maxcol,col)
        caption=''.join(self.render(c,False,active) for c in n.children if c.tag=='caption')
        caption=clean(caption)
        if maxcol==0:return caption
        rows=[[cells.get((r,c),'') for c in range(maxcol)] for r in range(rowcount)]
        headerindex=headers[0] if headers else (0 if self.options.get('opt-table-header-promotion') and rows else None)
        if headerindex is None:head=['']*maxcol
        else:head=rows.pop(headerindex)
        if skip:rows=[r for r in rows if any(x.strip() for x in r)]
        if skip and not rows and not any(head):return caption
        padding=self.options.get('opt-table-cell-padding-behavior') or 'aligned'
        widths=[max([len(head[c])]+[len(r[c]) for r in rows]+[1]) for c in range(maxcol)]
        def rowstr(row):
            if padding=='none':return '|'+'|'.join(row)+'|'
            if padding=='minimal':return '| '+' | '.join(row)+' |'
            return '| '+' | '.join(x+' '*(widths[c]-len(x)) for c,x in enumerate(row))+' |'
        sep=[]
        for c in range(maxcol):
            size=widths[c]+2 if padding=='aligned' else 3
            a=align.get(c)
            sep.append((':' if a in ('left','center') else '-')+'-'*(size-2)+(':' if a in ('right','center') else '-'))
        s=rowstr(head)+'\n|'+'|'.join(sep)+'|'
        for row in rows:s+='\n'+rowstr(row)
        return self.hold(s)+ ('\n\n'+caption if caption else '')
